const body = $input.first().json.body || $input.first().json;
const frozen_data = body.frozen_data || {};

return [{ json: {
  client_id:          body.client_id || frozen_data.user_id || 0,
  user_id:            body.client_id || frozen_data.user_id || 0,
  meta:               frozen_data.meta     || {},
  totaux:             frozen_data.totaux   || {},
  carriere:           frozen_data.carriere || {},
  revenu_souhaite:    body.revenu_souhaite || 0,
  scenarios_override: body.scenarios || null,
  frozen_data:        frozen_data,
  startTime:          Date.now()
} }];

// ============================================================================
// CONSTANTES 2025
// ============================================================================
const TAUX_PLEIN = 0.50;
const TAUX_MINIMAL = 0.375;
const DECOTE_PAR_TRIM = 0.0125;
const VALEUR_POINT_AGIRC_2025 = 1.4384;
const VALEUR_POINT_IRCANTEC_2025 = 0.47;
const VALEUR_POINT_RCI_2025 = 1.351;
const TAUX_PRELEVEMENT_NET = 0.091;
const AGE_TAUX_PLEIN_AUTO = 67;
const DUREES_REQUISES = {1958:167,1959:167,1960:167,1961:168,1962:169,1963:170,1964:171};

function parseDate(s) {
  s = s.trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return new Date(s + 'T00:00:00');
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(s)) {
    const p = s.split('/');
    return new Date(p[2] + '-' + p[1] + '-' + p[0] + 'T00:00:00');
  }
  return new Date(s);
}

function fmtDate(d) { return d.toISOString().split('T')[0]; }

function getDureeRequise(y) { return DUREES_REQUISES[y] || 172; }

function monthsBetween(d1, d2) {
  return (d2.getFullYear() - d1.getFullYear()) * 12 + (d2.getMonth() - d1.getMonth());
}

function addMonths(d, m) {
  const r = new Date(d); r.setMonth(r.getMonth() + m); return r;
}

function addYears(d, y) {
  const r = new Date(d); r.setFullYear(r.getFullYear() + y); return r;
}

function ageFloat(ddn, ref) {
  let y = ref.getFullYear() - ddn.getFullYear();
  let mo = ref.getMonth() - ddn.getMonth();
  let da = ref.getDate() - ddn.getDate();
  if (da < 0) mo--;
  if (mo < 0) { y--; mo += 12; }
  return y + mo / 12.0 + Math.max(da, 0) / 365.25;
}

function ageYM(ddn, ref) {
  let y = ref.getFullYear() - ddn.getFullYear();
  let mo = ref.getMonth() - ddn.getMonth();
  if (ref.getDate() < ddn.getDate()) mo--;
  if (mo < 0) { y--; mo += 12; }
  return { years: y, totalMonths: y * 12 + mo };
}

function trimAtDate(trim, ref, cible) {
  const diff = monthsBetween(ref, cible);
  return trim + Math.max(0, Math.floor(diff / 3));
}

function tauxCnav(trim, duree, age) {
  if (trim >= duree || age >= AGE_TAUX_PLEIN_AUTO) return TAUX_PLEIN;
  const manq = Math.min(duree - trim, 20);
  return Math.max(TAUX_PLEIN - manq * DECOTE_PAR_TRIM, TAUX_MINIMAL);
}

function pensionCnav(sam, taux, trimRg, duree) {
  return Math.round(sam * taux * Math.min(trimRg / duree, 1.0) / 12 * 100) / 100;
}

function dateTauxPlein(ddn, trimTous, ref) {
  const duree = getDureeRequise(ddn.getFullYear());
  const manq = Math.max(0, duree - trimTous);
  return addMonths(ref, Math.ceil(manq * 3));
}

function coeffAgirc(dateDepart, dateTp, age, isProgressive) {
  if (age >= AGE_TAUX_PLEIN_AUTO || isProgressive) return {coeff:1.00, duree:0};
  if (dateDepart >= addMonths(dateTp, 12)) return {coeff:1.00, duree:0};
  return {coeff:0.90, duree:36};
}

function calculScenario(code, ddStr, ddn, ref, dtp, sam, trimRg, trimTous, duree,
    agPts, agVp, ircPts, ircVp, rciPts, rciVp, isProg) {
  const dd = parseDate(ddStr);
  const trRg = trimAtDate(trimRg, ref, dd);
  const trTous = trimAtDate(trimTous, ref, dd);
  const age = ageYM(ddn, dd);
  const ageF = ageFloat(ddn, dd);
  const tc = tauxCnav(trTous, duree, ageF);
  const decTr = (trTous < duree && ageF < AGE_TAUX_PLEIN_AUTO) ? Math.max(0, Math.min(duree - trTous, 20)) : 0;
  const pc = pensionCnav(sam, tc, trRg, duree);
  const ca = coeffAgirc(dd, dtp, ageF, isProg);
  const pa = Math.round(agPts * agVp * ca.coeff / 12 * 100) / 100;
  const pi = Math.round(ircPts * ircVp / 12 * 100) / 100;
  const pr = Math.round(rciPts * rciVp / 12 * 100) / 100;
  const brut = Math.round((pc + pa + pi + pr) * 100) / 100;
  const net = Math.round(brut * (1 - TAUX_PRELEVEMENT_NET) * 100) / 100;
  return {
    code, date_depart: ddStr,
    age_depart_annees: age.years, age_depart_mois: age.totalMonths,
    trimestres_rg_at_depart: trRg, trimestres_acquis_tous: trTous,
    duree_requise: duree,
    taux_cnav: Math.round(tc * 100 * 100) / 100,
    decote_pct: Math.round(decTr * DECOTE_PAR_TRIM * 100 * 100) / 100,
    pension_cnav_mensuelle: pc,
    coefficient_agirc: ca.coeff, agirc_coeff_duree_mois: ca.duree,
    pension_agirc_mensuelle: pa, pension_ircantec_mensuelle: pi, pension_rci_mensuelle: pr,
    pension_totale_brute: brut, pension_totale_nette: net
  };
}

function projection20ans(scenarios, ref, agPts, agVp, inflation) {
  const horizons = [1,2,3,5,8,10,12,15,18,20];
  const agPlein = Math.round(agPts * agVp / 12 * 100) / 100;
  return horizons.map(annees => {
    const row = {horizon: annees, annee: ref.getFullYear() + annees};
    ['H1','H2','H3'].forEach(code => {
      if (!scenarios[code]) { row[code+'_cumul_nominal']=null; row[code+'_cumul_reel']=null; return; }
      const sc = scenarios[code];
      const dd = parseDate(sc.date_depart);
      const fin = addYears(ref, annees);
      let cum = 0, moisDep = 0, cur = new Date(ref);
      while (cur < fin) {
        if (cur >= dd) {
          const cm = (sc.agirc_coeff_duree_mois > 0 && moisDep < sc.agirc_coeff_duree_mois) ? 0.90 : 1.00;
          const ag = Math.round(agPlein * cm * 100) / 100;
          const net = Math.round((sc.pension_cnav_mensuelle + ag + sc.pension_ircantec_mensuelle + sc.pension_rci_mensuelle) * (1 - TAUX_PRELEVEMENT_NET) * 100) / 100;
          cum += net; moisDep++;
        }
        cur = addMonths(cur, 1);
      }
      row[code+'_cumul_nominal'] = Math.round(cum * 100) / 100;
      row[code+'_cumul_reel'] = Math.round(cum / Math.pow(1 + inflation, annees) * 100) / 100;
    });
    return row;
  });
}

function breakeven(scenarios) {
  if (!scenarios.H1 || !scenarios.H3) return {applicable:false, explication:'H1 et H3 requis.'};
  const h1 = scenarios.H1, h3 = scenarios.H3;
  const d1 = parseDate(h1.date_depart), d3 = parseDate(h3.date_depart);
  const n1 = h1.pension_totale_nette, n3 = h3.pension_totale_nette;
  if (d3 <= d1 && n3 >= n1) return {applicable:true, immediat:true, mois:0, date:h3.date_depart, explication:'H3 superieur a H1 des le depart.'};
  const moisGap = Math.max(0, monthsBetween(d1, d3));
  const capital = Math.round(n1 * moisGap * 100) / 100;
  const gain = Math.round((n3 - n1) * 100) / 100;
  if (gain <= 0) return {applicable:true, immediat:false, mois:null, date:null, explication:'H3 sans gain mensuel vs H1.', capital_perdu:capital, gain_mensuel:gain};
  const bm = Math.ceil(capital / gain);
  const bd = fmtDate(addMonths(d3, bm));
  return {
    applicable:true, immediat:false, mois:bm, date:bd,
    capital_perdu:capital, gain_mensuel:gain,
    explication:'H3 recupere l avance de H1 (' + capital.toFixed(2) + 'EUR) en ' + bm + ' mois grace a un gain mensuel de ' + gain.toFixed(2) + 'EUR.'
  };
}

function inflationImpact(p, inf) {
  return {
    valeur_reelle_5ans: Math.round(p / Math.pow(1+inf,5) * 100) / 100,
    valeur_reelle_10ans: Math.round(p / Math.pow(1+inf,10) * 100) / 100,
    valeur_reelle_20ans: Math.round(p / Math.pow(1+inf,20) * 100) / 100
  };
}

function apiHandler(params) {
  try {
    const ddn = parseDate(params.date_naissance);
    const sam = parseFloat(params.sam) || 0;
    const trimRg = parseInt(params.trimestres_cotises_rg) || 0;
    const trimTous = parseInt(params.trimestres_valides_tous_regimes) || 0;
    const ref = params.date_reference ? parseDate(params.date_reference) : new Date();
    ref.setHours(0,0,0,0);
    const trimEtr = parseInt(params.trimestres_etranger) || 0;
    const agPts = parseFloat(params.agirc_points) || 0;
    const agVp = parseFloat(params.agirc_valeur_point) || VALEUR_POINT_AGIRC_2025;
    const ircPts = parseFloat(params.ircantec_points) || 0;
    const ircVp = parseFloat(params.ircantec_valeur_point) || VALEUR_POINT_IRCANTEC_2025;
    const rciPts = parseFloat(params.rci_points) || 0;
    const rciVp = parseFloat(params.rci_valeur_point) || VALEUR_POINT_RCI_2025;
    const revSouh = params.revenu_souhaite ? parseFloat(params.revenu_souhaite) : null;
    const inflation = parseFloat(params.inflation) || 0.02;
    const trimPourTp = trimTous + trimEtr;
    const duree = getDureeRequise(ddn.getFullYear());
    const dtp = dateTauxPlein(ddn, trimPourTp, ref);
    const scenarios = {};
    for (const [code, sc] of Object.entries(params.scenarios)) {
      scenarios[code] = calculScenario(code, sc.date_depart, ddn, ref, dtp, sam,
        trimRg, trimPourTp, duree, agPts, agVp, ircPts, ircVp, rciPts, rciVp, sc.is_progressive || false);
    }
    const proj = projection20ans(scenarios, ref, agPts, agVp, inflation);
    const be = breakeven(scenarios);
    const comp = {};
    if (scenarios.H1 && scenarios.H3) {
      const em = Math.round((scenarios.H3.pension_totale_nette - scenarios.H1.pension_totale_nette) * 100) / 100;
      comp.ecart_H3_H1_mensuel = em;
      comp.ecart_H3_H1_annuel = Math.round(em * 12 * 100) / 100;
    }
    const refPens = (scenarios.H3 || scenarios.H1 || {}).pension_totale_nette || 0;
    const infImp = refPens ? inflationImpact(refPens, inflation) : {};
    const deficit = {};
    if (revSouh !== null) {
      const ph3 = refPens;
      const dm = Math.round((revSouh - ph3) * 100) / 100;
      let cap = 0;
      if (dm > 0) {
        const mr = inflation / 12, n = 240;
        cap = mr > 0 ? Math.round(dm * (1 - Math.pow(1+mr,-n)) / mr * 100) / 100 : Math.round(dm * n * 100) / 100;
      }
      deficit.revenu_souhaite = revSouh; deficit.pension_H3_nette = ph3;
      deficit.deficit_mensuel = dm; deficit.capital_necessaire_20ans = cap;
    }
    const etr = {
      detected: trimEtr > 0, trimestres_etranger: trimEtr,
      impact: trimEtr > 0 ? (trimEtr + ' trimestre(s) etranger(s) pris en compte pour le taux plein. Non inclus dans la proratisation CNAV.') : 'Aucun trimestre etranger declare.'
    };
    return {scenarios, date_taux_plein: fmtDate(dtp), duree_requise: duree, comparatif: comp,
      projection_20ans: proj, breakeven: be, deficit, inflation_impact: infImp, etranger: etr,
      source_calcul: 'js-simulation-v1'};
  } catch(e) {
    return {erreur: true, message: 'Erreur calcul: ' + e.message, type: 'erreur_calcul'};
  }
}

// === N8N DATA EXTRACTION ===
const prep = $input.all()[0].json;
const frozen_data = prep.frozen_data || {};
const totaux = frozen_data.totaux || {};
const meta = frozen_data.meta || {};
let _ddn = meta.date_naissance || meta.ddn || '';
let _dl = totaux.date_depart_legal || '';
let _dt = totaux.date_taux_plein || '';
let _do = totaux.date_optimale || '';
if (_ddn && (!_dl || !_dt)) {
  try {
    const d = parseDate(_ddn);
    if (!_dl) _dl = fmtDate(addYears(d, 64));
    if (!_dt) _dt = fmtDate(addYears(d, 67));
    if (!_do) _do = _dt;
  } catch(e) {}
}
const _tr = parseInt(totaux.trimestres_cotises_rg || totaux.trimestres_rg || totaux.trimestres_cotises || 0);
const _tt = parseInt(totaux.trimestres_valides_tous_regimes || totaux.trimestres_total || totaux.trimestres_tous_regimes || 0);
const _sam = parseFloat(totaux.sam || totaux.sam_cnav || 0);
const _po = (typeof totaux.points_officiels === 'object' && totaux.points_officiels) ? totaux.points_officiels : {};
const _ag = parseFloat(totaux.agirc_points || totaux.points_agirc || _po.agirc || _po.agirc_arrco || 0);
const _ir = parseFloat(totaux.ircantec_points || totaux.points_ircantec || _po.ircantec || 0);
const _rc = parseFloat(totaux.rci_points || totaux.points_rci || _po.rci || 0);
const params_calcul = {
  date_naissance: _ddn || '01/01/1965',
  date_reference: new Date().toISOString().split('T')[0],
  sam: _sam,
  trimestres_cotises_rg: _tr,
  trimestres_valides_tous_regimes: _tt,
  trimestres_etranger: parseInt(totaux.trimestres_etranger || 0),
  agirc_points: _ag, agirc_valeur_point: 1.4384,
  ircantec_points: _ir, ircantec_valeur_point: 0.47,
  rci_points: _rc, rci_valeur_point: 1.351,
  revenu_souhaite: parseFloat(prep.revenu_souhaite || 0),
  inflation: 0.02,
  scenarios: prep.scenarios_override || {
    H1: {date_depart: _dl},
    H2: {date_depart: _dt},
    H3: {date_depart: _do || _dt}
  }
};
const result = apiHandler(params_calcul);
return [{json: {calcul: result, meta, totaux, client_id: prep.client_id || frozen_data.user_id || 0}}];

const calc = $input.first().json.calcul || {};
const meta = $input.first().json.meta || {};
const totaux = $input.first().json.totaux || {};
const client_id = $input.first().json.client_id || $('PREP PAYLOAD').first().json.client_id;

const sc = calc.scenarios || {};
const H1 = sc.H1 || {};
const H2 = sc.H2 || {};
const H3 = sc.H3 || {};

const fmt = (v) => v ? Number(v).toLocaleString('fr-FR', {minimumFractionDigits: 2, maximumFractionDigits: 2}) : '0,00';

const proj = (calc.projection_20ans || []).map(r =>
  `<tr><td>${r.horizon}</td><td>${r.annee}</td>` +
  `<td>${(r.H1_cumul_nominal||0).toLocaleString('fr-FR')} €</td>` +
  `<td>${(r.H2_cumul_nominal||0).toLocaleString('fr-FR')} €</td>` +
  `<td style="background:#d1fae5;font-weight:700">${(r.H3_cumul_nominal||0).toLocaleString('fr-FR')} €</td></tr>`
).join('');

const be = calc.breakeven || {};
const def = calc.deficit || {};
const inf = calc.inflation_impact || {};

return [{ json: {
  context: {
    CLIENT_NOM: meta.nom_complet || meta.nom || 'Client',
    CLIENT_CIVILITE: meta.civilite || 'Monsieur',
    DATE_SIM: new Date().toLocaleDateString('fr-FR'),
    DATE_TAUX_PLEIN: calc.date_taux_plein || '',
    DUREE_REQUISE: calc.duree_requise || 172,
    H1_DATE: H1.date_depart || '', H1_AGE: `${H1.age_depart_annees||''} ans`,
    H1_TRIMESTRES: H1.trimestres_acquis_tous || '', H1_TAUX_CNAV: H1.taux_cnav || '',
    H1_CNAV: fmt(H1.pension_cnav_mensuelle), H1_AGIRC: fmt(H1.pension_agirc_mensuelle),
    H1_IRCANTEC: fmt(H1.pension_ircantec_mensuelle), H1_RCI: fmt(H1.pension_rci_mensuelle),
    H1_TOTAL_BRUT: fmt(H1.pension_totale_brute), H1_TOTAL_NET: fmt(H1.pension_totale_nette),
    H1_COEFF_AGIRC: H1.coefficient_agirc || 1, H1_COEFF_DUREE: H1.agirc_coeff_duree_mois || 0,
    H2_DATE: H2.date_depart || '', H2_AGE: `${H2.age_depart_annees||''} ans`,
    H2_TRIMESTRES: H2.trimestres_acquis_tous || '', H2_TAUX_CNAV: H2.taux_cnav || '',
    H2_CNAV: fmt(H2.pension_cnav_mensuelle), H2_AGIRC: fmt(H2.pension_agirc_mensuelle),
    H2_IRCANTEC: fmt(H2.pension_ircantec_mensuelle), H2_RCI: fmt(H2.pension_rci_mensuelle),
    H2_TOTAL_BRUT: fmt(H2.pension_totale_brute), H2_TOTAL_NET: fmt(H2.pension_totale_nette),
    H2_COEFF_AGIRC: H2.coefficient_agirc || 1, H2_COEFF_DUREE: H2.agirc_coeff_duree_mois || 0,
    H3_DATE: H3.date_depart || '', H3_AGE: `${H3.age_depart_annees||''} ans`,
    H3_TRIMESTRES: H3.trimestres_acquis_tous || '', H3_TAUX_CNAV: H3.taux_cnav || '',
    H3_CNAV: fmt(H3.pension_cnav_mensuelle), H3_AGIRC: fmt(H3.pension_agirc_mensuelle),
    H3_IRCANTEC: fmt(H3.pension_ircantec_mensuelle), H3_RCI: fmt(H3.pension_rci_mensuelle),
    H3_TOTAL_BRUT: fmt(H3.pension_totale_brute), H3_TOTAL_NET: fmt(H3.pension_totale_nette),
    H3_COEFF_AGIRC: H3.coefficient_agirc || 1, H3_COEFF_DUREE: H3.agirc_coeff_duree_mois || 0,
    ECART_H3_H1: fmt((calc.comparatif||{}).ecart_H3_H1_mensuel),
    ECART_H3_H1_AN: fmt((calc.comparatif||{}).ecart_H3_H1_annuel),
    TABLEAU_PROJECTION: proj,
    BREAKEVEN_MOIS: be.immediat ? 'Immédiat' : (be.mois || 'N/A'),
    BREAKEVEN_DATE: be.date || '',
    BREAKEVEN_EXPLICATION: be.explication || '',
    DEFICIT_MENSUEL: fmt(def.deficit_mensuel),
    REVENU_SOUHAITE: fmt(def.revenu_souhaite),
    CAPITAL_NECESSAIRE: (def.capital_necessaire_20ans||0).toLocaleString('fr-FR'),
    H3_REEL_5ANS: fmt(inf.valeur_reelle_5ans),
    H3_REEL_10ANS: fmt(inf.valeur_reelle_10ans),
    H3_REEL_20ANS: fmt(inf.valeur_reelle_20ans),
    ETRANGER_IMPACT: (calc.etranger||{}).impact || 'Aucune période étrangère détectée.',
  },
  calcul: calc,
  client_id
} }];

var html = $input.first().json;
var raw = '';
if (html.text) raw = html.text;
else if (typeof html.response === 'string') raw = html.response;
else raw = JSON.stringify(html);

var t = raw.trim();
if (t.charAt(0) === '"' && t.charAt(t.length-1) === '"') {
  try { raw = JSON.parse(t); } catch(e) { raw = t.slice(1,-1); }
}
for (var i=0;i<3;i++) {
  raw = raw.split('\\n').join('\n').split('\\'+'"').join('"');
}
raw = raw.trim();
if (raw.startsWith('```html')) raw = raw.slice(7);
else if (raw.startsWith('```')) raw = raw.slice(3);
if (raw.endsWith('```')) raw = raw.slice(0,-3);
raw = raw.trim();

const calcul = $('PYTHON CALC ENGINE').first().json.calcul;
const client_id = $('PREP PAYLOAD').first().json.client_id;

return [{ json: { html_report: raw, calcul_json: calcul, client_id } }];

const items = $input.all();

// Extract text from each agent
const extractText = (item) => {
  const j = item.json;
  return j.text || j.output || (j.response && typeof j.response.text === 'string' ? j.response.text : '') || JSON.stringify(j);
};

const texts = items.map(extractText);

// Try to identify which agent produced which output by content
let analyseText = '', planText = '', risquesText = '';
for (const t of texts) {
  const lower = t.toLowerCase();
  if (lower.includes('actions') || lower.includes('priorite') || lower.includes('echeance') || t.trim().startsWith('{')) {
    planText = t;
  } else if (lower.includes('longévité') || lower.includes('per') || lower.includes('assurance-vie') || lower.includes('épargne')) {
    risquesText = t;
  } else {
    analyseText = t;
  }
}

// Parse plan JSON if possible
let planActions = [];
try {
  const cleaned = planText.trim().replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  planActions = parsed.actions || [];
} catch(e) {
  planActions = [];
}

// Build enriched context
const baseContext = $('BUILD CONTEXT').first().json.context;
const calcul = $('BUILD CONTEXT').first().json.calcul;
const client_id = $('BUILD CONTEXT').first().json.client_id;

const enrichedContext = {
  ...baseContext,
  ANALYSE_COMPARATIVE: analyseText,
  ANALYSE_CNAV: analyseText,
  ANALYSE_AGIRC: analyseText,
  ANALYSE_BREAKEVEN: analyseText,
  ANALYSE_PROJECTION: analyseText,
  PLAN_ACTIONS: planActions,
  TABLEAU_PLAN_ACTION: planActions.map(a =>
    `<tr><td><span class="badge badge-${a.priorite === 'URGENT' ? 'red' : a.priorite === 'IMPORTANT' ? 'orange' : 'green'}">${a.priorite}</span></td><td>${a.action}</td><td>${a.echeance}</td><td>${a.responsable}</td></tr>`
  ).join(''),
  ANALYSE_DEFICIT: risquesText,
  ANALYSE_INFLATION: risquesText,
  ANALYSE_RISQUES: risquesText,
  CONCLUSION_PERSONNALISEE: analyseText
};

return [{ json: { context: enrichedContext, calcul, client_id } }];
